112	    /** Move a claim to a new status; a change its status does not allow is refused, as is the user
113	     *  who opened a claim settling it. A clerk settling a claim whose due is above the clerk limit
114	     *  leaves it PENDING a steward's approval instead. */
115	    @Transactional
116	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
117	        Person person = person(sheetId, personId);
118	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
119	        // read below is its latest state.
120	        if (to == ClaimStatus.OPEN) {
121	            sheets.lock(sheetId);
122	        }
123	        Claim claim = claim(sheetId, personId, id);
124	        refuseClosed(sheetId, claim.getDate());
125	        if (!claim.getStatus().canMoveTo(to)) {
126	            throw new StatusChangeRefusedException(claim.getStatus(), to);
127	        }
128	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
129	            throw new OwnClaimSettleRefusedException(user);
130	        }
131	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
132	            throw new StatusChangeRefusedException(claim.getStatus(), to);
133	        }
134	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
135	        // gathered by then.
136	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
137	        if (to == ClaimStatus.SETTLED) {
138	            refuseUnproved(sheetId, claim, due);
139	        }
140	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
141	            to = ClaimStatus.PENDING;
142	        }
143	        claim.setStatus(to);
144	        if (to == ClaimStatus.OPEN) {
145	            claim.setNumber(nextNumber(sheetId, claim.getDate()));
146	            claim.setOpenedBy(user);
147	        } else if (to == ClaimStatus.SETTLED) {
148	            claim.setSettledDue(due);
149	        }
150	        Claim saved = claims.saveAndFlush(claim);
151	        log(sheetId, user, person, saved);
152	        String event = switch (to) {
153	            case OPEN -> "CLAIM_OPENED";
154	            case PENDING -> "CLAIM_PENDING";
155	            case SETTLED -> "CLAIM_SETTLED";
156	            case VOID -> "CLAIM_VOIDED";
157	            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
158	        };
159	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
160	        if (to == ClaimStatus.SETTLED) {
161	            line += " due=" + settledDueText(saved);
162	        }
163	        audit.recordOnCommit(line);
164	        return saved;
165	    }
