353	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
354	     *  after it) the next within the period its date falls in, <period>-<n>, or X-<n> when it falls
355	     *  in none; otherwise the sheet's next sheet-wide number. Taken with the sheet locked. */
356	    private String nextNumber(String sheetId, LocalDate date) {
357	        LocalDate from = settings.periodNumberingFrom(sheetId);
358	        if (from == null || sheets.today(sheetId).isBefore(from)) {
359	            return String.valueOf(sheets.nextClaimNumber(sheetId));
360	        }
361	        String prefix = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
362	                .filter(period -> period.contains(date))
363	                .findFirst().map(Period::getName).orElse(NO_PERIOD) + "-";
364	        long last = claims.numbers(sheetId).stream()
365	                .filter(number -> number.startsWith(prefix))
366	                .map(number -> number.substring(prefix.length()))
367	                .filter(n -> n.matches("\\d{1,18}"))
368	                .mapToLong(Long::parseLong)
369	                .max().orElse(0);
370	        return prefix + (last + 1);
371	    }
