79	  readonly roles = signal<RoleView[]>([]);
80	  /** Every value recorded for the dated settings, by key. */
81	  readonly dated = signal<Record<string, DatedValue[]>>({});
82	  /** The clerk limit in force on the sheet's today; null when there is none. */
83	  readonly clerkLimit = computed(() => this.onToday('clerk-limit') ?? null);
84	  /** The floor in force on the sheet's today. */
85	  readonly floor = computed(() => this.onToday('floor') ?? FLOOR);
86	  /** The cap in force on the sheet's today; null when there is none. */
87	  readonly cap = computed(() => this.onToday('cap') ?? null);
88	  /** The proof threshold in force on the sheet's today; null when there is none. */
89	  readonly proofThreshold = computed(() => this.onToday('proof-threshold') ?? null);
90	  /** The terms in force on the sheet's today. */
91	  readonly terms = computed(() => Number(this.onToday('terms') ?? TERMS));
92	  /** The late percent in force on the sheet's today. */
93	  readonly latePct = computed(() => this.onToday('late-pct') ?? LATE_PCT);
94	  /** The grades' own terms in force on the sheet's today, by grade; a grade not listed takes the
95	   *  sheet's terms. */
96	  readonly gradeTerms = computed(() => {
97	    const byGrade: Record<string, number> = {};
98	    for (const g of GRADES) {
99	      const days = this.onToday(`terms-${g}`);
100	      if (days !== undefined && days !== null) byGrade[g] = Number(days);
101	    }
102	    return byGrade;
103	  });
104	  /** The floor in force on a date: the least the live due of a claim of that date can be. */
105	  readonly floorOn = computed(() => {
106	    const recorded = this.dated()['floor'];
107	    return (date: string) => valueOn(recorded, date) ?? FLOOR;
108	  });
109	  /** The late percent in force on a date: what an overdue claim of that date gains. */
110	  readonly latePctOn = computed(() => {
111	    const recorded = this.dated()['late-pct'];
112	    return (date: string) => valueOn(recorded, date) ?? LATE_PCT;
113	  });
114	  readonly policyDate = signal('');
115	  readonly periodNumberingFrom = signal('');
