600	      await this.store.setRole(user, role);
601	    } catch {
602	      this.roleError.set(`The role of ${user} could not be set.`);
603	    } finally {
604	      this.busy.set(false);
605	    }
606	  }
607	
608	  /** Save the settings typed. A submit while an earlier one is waiting for its answer is saved
609	   *  after it, with the values typed when it was submitted. */
610	  protected async saveSettings(event: Event): Promise<void> {
611	    event.preventDefault();
612	    this.settingsError.set(null);
613	    const limit = this.clerkLimit().trim();
614	    const floor = this.floor().trim();
615	    const saveLimit = this.clerkLimitTyped();
616	    const saveFloor = this.floorTyped();
617	    const cap = this.cap().trim();
618	    const saveCap = this.capTyped();
619	    const threshold = this.proofThreshold().trim();
620	    const saveThreshold = this.proofThresholdTyped();
621	    const terms = this.terms().trim();
622	    const saveTerms = this.termsTyped();
623	    const gradeTerms = Object.entries(this.gradeTerms()).map(([grade, days]) => [grade, days.trim()] as const);
624	    const latePct = this.latePct().trim();
625	    const saveLatePct = this.latePctTyped();
626	    const policyDate = this.policyDate().trim();
627	    const savePolicyDate = this.policyDateTyped();
628	    const numberingFrom = this.periodNumberingFrom().trim();
629	    const saveNumberingFrom = this.periodNumberingFromTyped();
630	    const limitFrom = this.clerkLimitFrom().trim();
631	    const floorFrom = this.floorFrom().trim();
632	    const capFrom = this.capFrom().trim();
633	    const thresholdFrom = this.proofThresholdFrom().trim();
634	    const termsFrom = this.termsFrom().trim();
635	    const latePctFrom = this.latePctFrom().trim();
636	    const gradeTermsFrom: Record<string, string> = Object.fromEntries(
637	      Object.entries(this.gradeTermsFrom()).map(([grade, from]) => [grade, from.trim()]),
638	    );
639	    const froms: [boolean, string, string][] = [
640	      [saveLimit, limitFrom, 'the clerk limit'],
641	      [saveFloor, floorFrom, 'the floor'],
642	      [saveCap, capFrom, 'the cap'],
643	      [saveThreshold, thresholdFrom, 'the proof threshold'],
644	      [saveTerms, termsFrom, 'the terms'],
645	      ...gradeTerms.map(([grade]) => [true, gradeTermsFrom[grade] ?? '', `the terms for grade ${grade}`] as [boolean, string, string]),
646	      [saveLatePct, latePctFrom, 'the late percent'],
647	    ];
648	    if (saveLimit && limit !== '' && !AMOUNT.test(limit)) {
649	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank for none.');
650	      return;
651	    }
652	    if (saveFloor && !AMOUNT.test(floor)) {
653	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
654	      return;
655	    }
656	    if (saveCap && cap !== '' && !AMOUNT.test(cap)) {
657	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it blank for none.');
658	      return;
659	    }
660	    if (saveThreshold && threshold !== '' && !AMOUNT.test(threshold)) {
661	      this.settingsError.set('Type a proof threshold of 0.00 or more, with up to two decimals, or leave it blank for none.');
662	      return;
663	    }
664	    if (saveTerms && !DAYS.test(terms)) {
665	      this.settingsError.set('Type terms of 0 or more whole days.');
666	      return;
667	    }
668	    const badGrade = gradeTerms.find(([, days]) => !DAYS.test(days));
669	    if (badGrade) {
670	      this.settingsError.set(`Type terms for grade ${badGrade[0]} of 0 or more whole days.`);
671	      return;
672	    }
673	    if (saveLatePct && !AMOUNT.test(latePct)) {
674	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
675	      return;
676	    }
677	    const badFrom = froms.find(([save, from]) => save && from !== '' && !DATE.test(from));
678	    if (badFrom) {
679	      this.settingsError.set(`Type the from-date of ${badFrom[2]} as yyyy-mm-dd, or leave it blank for the sheet's today.`);
680	      return;
681	    }
682	    if (savePolicyDate && policyDate !== '' && !DATE.test(policyDate)) {
683	      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
684	      return;
685	    }
686	    if (saveNumberingFrom && numberingFrom !== '' && !DATE.test(numberingFrom)) {
687	      this.settingsError.set('Type a period numbering from date as yyyy-mm-dd, or leave it blank for off.');
688	      return;
689	    }
690	    const fromOf = (from: string) => (from === '' ? null : from);
691	    this.clerkLimitTyped.set(false);
692	    this.floorTyped.set(false);
693	    this.capTyped.set(false);
694	    this.proofThresholdTyped.set(false);
695	    this.termsTyped.set(false);
696	    this.gradeTerms.set({});
697	    this.latePctTyped.set(false);
698	    this.policyDateTyped.set(false);
699	    this.periodNumberingFromTyped.set(false);
700	    const save = async () => {
701	      try {
702	        if (saveLimit) await this.store.setClerkLimit(limit === '' ? null : limit, fromOf(limitFrom));
703	        if (saveFloor) await this.store.setFloor(floor, fromOf(floorFrom));
704	        if (saveCap) await this.store.setCap(cap === '' ? null : cap, fromOf(capFrom));
705	        if (saveThreshold) await this.store.setProofThreshold(threshold === '' ? null : threshold, fromOf(thresholdFrom));
706	        if (saveTerms) await this.store.setTerms(Number(terms), fromOf(termsFrom));
707	        for (const [grade, days] of gradeTerms) {
708	          await this.store.setGradeTerms(grade, Number(days), fromOf(gradeTermsFrom[grade] ?? ''));
709	        }
710	        if (saveLatePct) await this.store.setLatePct(latePct, fromOf(latePctFrom));
711	        if (savePolicyDate) await this.store.setPolicyDate(policyDate === '' ? null : policyDate);
712	        if (saveNumberingFrom) await this.store.setPeriodNumberingFrom(numberingFrom === '' ? null : numberingFrom);
713	      } catch {
714	        // What was typed stays to be saved again.
715	        if (saveLimit) this.clerkLimitTyped.set(true);
716	        if (saveFloor) this.floorTyped.set(true);
717	        if (saveCap) this.capTyped.set(true);
718	        if (saveThreshold) this.proofThresholdTyped.set(true);
719	        if (saveTerms) this.termsTyped.set(true);
720	        this.gradeTerms.update((typed) => ({ ...Object.fromEntries(gradeTerms), ...typed }));
721	        if (saveLatePct) this.latePctTyped.set(true);
722	        if (savePolicyDate) this.policyDateTyped.set(true);
723	        if (saveNumberingFrom) this.periodNumberingFromTyped.set(true);
724	        this.settingsError.set('The settings could not be saved.');
725	      }
726	    };
727	    this.settingsSaves = this.settingsSaves.then(save);
728	    await this.settingsSaves;
729	  }
730	}
